(6471404, 962094, 54645, '<td valign="top">Good use of light and bokeh. The emerging pieces in the right third are captivating.</td>', 'Good use of light and bokeh. The emerging pieces in the right third are captivating.', '2011-07-15 12:31:00.000000', NULL, 1),
(6471405, 961833, 54645, '<td valign="top">A fortified layers</td>', 'A fortified layers', '2011-07-15 12:32:26.000000', NULL, 1),
(6471406, 962246, 54645, '<td valign="top">Smart woman! The degree of blur adds to her indecision; not intense enough to indicate that she is running as fast as she can from Grog, but just subtle enough to imply that she may be back.</td>', 'Smart woman! The degree of blur adds to her indecision; not intense enough to indicate that she is running as fast as she can from Grog, but just subtle enough to imply that she may be back.', '2011-07-15 12:34:13.000000', NULL, 1),
