(6471529, 962036, 12611, '<td valign="top">Nice work; certainly catches the quirkiness of the style of bspurgeon.</td>', 'Nice work; certainly catches the quirkiness of the style of bspurgeon.', '2011-07-15 14:40:20.000000', NULL, 1),
(6471530, 962032, 12611, '<td valign="top">perhaps too clever?</td>', 'perhaps too clever?', '2011-07-15 14:40:48.000000', NULL, 1),
