(6475601, 961933, 76335, '<td valign="top">Backyard bliss -- Ben''s way. The lines and energy all seem to be directed toward the ball. I feel like I''m part of the game.</td>', 'Backyard bliss -- Ben''s way. The lines and energy all seem to be directed toward the ball. I feel like I''m part of the game.', '2011-07-19 18:56:10.000000', NULL, 1),
(6475612, 962227, 76335, '<td valign="top">Who knew something so simple and mundane as chives could be presented to look like a one-eyed sea monster? Ben knows a thing or two about sea monsters. A clever vision you had for this out-of-the-proverbial-box still life.</td>', 'Who knew something so simple and mundane as chives could be presented to look like a one-eyed sea monster? Ben knows a thing or two about sea monsters. A clever vision you had for this out-of-the-proverbial-box still life.', '2011-07-19 19:20:49.000000', NULL, 1),
(6475613, 962123, 34171, '<td valign="top">I like it, the comp works well.</td>', 'I like it, the comp works well.', '2011-07-19 19:21:04.000000', NULL, 1),
(6475615, 962148, 76335, '<td valign="top">Textures, gritty and colorful. A little bit of motion blur is present, I think, but your vision for this comes through.</td>', 'Textures, gritty and colorful. A little bit of motion blur is present, I think, but your vision for this comes through.', '2011-07-19 19:22:07.000000', NULL, 1),
(6475616, 961165, 34171, '<td valign="top">Beautiful work here with great dof.</td>', 'Beautiful work here with great dof.', '2011-07-19 19:22:08.000000', NULL, 1),
