(6475619, 962026, 76335, '<td valign="top">I appreciate something different from zoo shots. Curves and stripes and shadows playfully compete here. The framing makes this almost abstract -- almost but not quite. We can still apprecaite their zebra-ness... <br/> <br/>Zebra-ness? Did I just type that?!</td>', 'I appreciate something different from zoo shots. Curves and stripes and shadows playfully compete here. The framing makes this almost abstract -- almost but not quite. We can still apprecaite their zebra-ness...  Zebra-ness? Did I just type that?!', '2011-07-19 19:24:46.000000', NULL, 1),
(6475621, 961881, 34171, '<td valign="top">Better framing and crop would have made this a great image IMHO.  I still like it though.</td>', 'Better framing and crop would have made this a great image IMHO.  I still like it though.', '2011-07-19 19:27:38.000000', NULL, 1),
(6475654, 962324, 76335, '<td valign="top">Quirky yet captivating. I wonder what they''re constructing? The light is as crushing as any I-beam.</td>', 'Quirky yet captivating. I wonder what they''re constructing? The light is as crushing as any I-beam.', '2011-07-19 20:09:24.000000', NULL, 1),
(6475657, 961453, 76335, '<td valign="top">Horizon and shoreline frame a huge mass of water -- and our simple subject, confined but quite relaxed in a corner of the frame. A well crafted composition.</td>', 'Horizon and shoreline frame a huge mass of water -- and our simple subject, confined but quite relaxed in a corner of the frame. A well crafted composition.', '2011-07-19 20:13:13.000000', NULL, 1),
(6475668, 962162, 76335, '<td valign="top">The ball sits in the sky like a planet or a strange moon. The cloud counterbalances it in an interesting way. You''ve captured something magical in the way you''ve stopped time.</td>', 'The ball sits in the sky like a planet or a strange moon. The cloud counterbalances it in an interesting way. You''ve captured something magical in the way you''ve stopped time.', '2011-07-19 20:23:14.000000', NULL, 1),
