(6477924, 962056, 126709, '<td valign="top">Like the title, the shadows, and the trees framing the shot. So many great photos in this challenge.</td>', 'Like the title, the shadows, and the trees framing the shot. So many great photos in this challenge.', '2011-07-21 19:16:49.000000', NULL, 1),
(6477926, 962117, 126709, '<td valign="top">So smooth.  I want to roll my pants up and wade into the receding wave.</td>', 'So smooth.  I want to roll my pants up and wade into the receding wave.', '2011-07-21 19:19:00.000000', NULL, 1),
(6477928, 962305, 126709, '<td valign="top">A bit blown out in spots.  Hard to make out as water at first glance.</td>', 'A bit blown out in spots.  Hard to make out as water at first glance.', '2011-07-21 19:19:43.000000', NULL, 1),
(6477929, 961357, 126709, '<td valign="top">I don''t know if the title works for this but I like the photo. I like the contrast and light.</td>', 'I don''t know if the title works for this but I like the photo. I like the contrast and light.', '2011-07-21 19:19:52.000000', NULL, 1),
(6477930, 962299, 126709, '<td valign="top">Nice light.</td>', 'Nice light.', '2011-07-21 19:20:36.000000', NULL, 1),
(6477931, 962240, 126709, '<td valign="top">It does feel disenchanted.  I believe anymore contrast would take that feeling away.  Nice photo.</td>', 'It does feel disenchanted.  I believe anymore contrast would take that feeling away.  Nice photo.', '2011-07-21 19:20:55.000000', NULL, 1),
(6477933, 962288, 126709, '<td valign="top">Very nice in BW.</td>', 'Very nice in BW.', '2011-07-21 19:21:30.000000', NULL, 1),
(6477935, 962293, 126709, '<td valign="top">What a dramatic sky.</td>', 'What a dramatic sky.', '2011-07-21 19:23:24.000000', NULL, 1),
(6477936, 962015, 126709, '<td valign="top">I like how the word love stands out on the heart.  As if a child is reaching for the emotion.</td>', 'I like how the word love stands out on the heart.  As if a child is reaching for the emotion.', '2011-07-21 19:23:48.000000', NULL, 1),
(6477938, 962215, 126709, '<td valign="top">I didn''t connect the photo to the title but I like the composition.</td>', 'I didn''t connect the photo to the title but I like the composition.', '2011-07-21 19:24:06.000000', NULL, 1),
(6477939, 962259, 126709, '<td valign="top">Nice use of the glass.</td>', 'Nice use of the glass.', '2011-07-21 19:24:10.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6477943, 962098, 126709, '<td valign="top">The hustle and wait of air travelers. Nice hints of both..</td>', 'The hustle and wait of air travelers. Nice hints of both..', '2011-07-21 19:27:35.000000', NULL, 1),
(6477947, 962153, 126709, '<td valign="top">Sorry to disappoint (title) but I like this.</td>', 'Sorry to disappoint (title) but I like this.', '2011-07-21 19:28:48.000000', NULL, 1),
(6477951, 962320, 126709, '<td valign="top">I wish it was a person in shadow behind the pane.</td>', 'I wish it was a person in shadow behind the pane.', '2011-07-21 19:32:11.000000', NULL, 1),
(6477962, 961404, 63918, '<td valign="top">Wonderful mood and tones! Great shot! By my count, this should ribbon.</td>', 'Wonderful mood and tones! Great shot! By my count, this should ribbon.', '2011-07-21 20:09:45.000000', NULL, 1),
(6477971, 962321, 64086, '<td valign="top">Beautiful zen atmosphere.</td>', 'Beautiful zen atmosphere.', '2011-07-21 20:22:53.000000', NULL, 1),
(6477980, 962325, 32011, '<td valign="top">Kid without head, blur, b&amp;w, at a beach... this SCREAMS Ben''s style. Excellent entry.</td>', 'Kid without head, blur, b&w, at a beach... this SCREAMS Ben''s style. Excellent entry.', '2011-07-21 20:42:49.000000', NULL, 1),
(6477983, 962103, 32011, '<td valign="top">I like this... a lot.  Don''t know exactly why... it''s <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=54645" rel="nofollow" target="_blank">bspurgeon</a>-ish, but there''s something amiss, imho, however, I''m captivated by this and therefore have still score this quite high (voted earlier, am only commenting now).  Unfortunately, I suspect this may be a candidate for a MUAIMHO... a small consolation if it is... we''ll see when voting finishes.  Regardless... well done on a very nice entry.</td>', 'I like this... a lot.  Don''t know exactly why... it''s  bspurgeon-ish, but there''s something amiss, imho, however, I''m captivated by this and therefore have still score this quite high (voted earlier, am only commenting now).  Unfortunately, I suspect this may be a candidate for a MUAIMHO... a small consolation if it is... we''ll see when voting finishes.  Regardless... well done on a very nice entry.', '2011-07-21 20:46:53.000000', NULL, 1),
(6477994, 961159, 32011, '<td valign="top">Very nice.  Combination of sharpness and blur... very nice.  The rock adds interest and the processing is perfect for the challenge.  I took a few shots like this for this challenge, but none as good as this.  Well done.</td>', 'Very nice.  Combination of sharpness and blur... very nice.  The rock adds interest and the processing is perfect for the challenge.  I took a few shots like this for this challenge, but none as good as this.  Well done.', '2011-07-21 21:00:36.000000', NULL, 1),
(6477996, 962097, 32011, '<td valign="top">Yet another of the many great images in this challenge.  Perfect balance of sharpness and blur.  Great processing.  Wonderful composition and it tells a story.  Excellent entry.</td>', 'Yet another of the many great images in this challenge.  Perfect balance of sharpness and blur.  Great processing.  Wonderful composition and it tells a story.  Excellent entry.', '2011-07-21 21:01:51.000000', NULL, 1),
(6478006, 962185, 119419, '<td valign="top">This has Sarah written all over it. Wonderful Bokeh, gives me a feeling of tallness ;) Nice one.</td>', 'This has Sarah written all over it. Wonderful Bokeh, gives me a feeling of tallness ;) Nice one.', '2011-07-21 21:22:56.000000', NULL, 1),
(6478007, 962073, 119419, '<td valign="top">Lovely smooth grain, the water drops really give a sense of closeness and intimacy.</td>', 'Lovely smooth grain, the water drops really give a sense of closeness and intimacy.', '2011-07-21 21:24:19.000000', NULL, 1),
(6478008, 962026, 119419, '<td valign="top">Lovely light and subject</td>', 'Lovely light and subject', '2011-07-21 21:24:25.000000', NULL, 1),
(6478009, 961447, 119419, '<td valign="top">Lucky boy, unlucky fish. Great Ben a like shot, nice toning.</td>', 'Lucky boy, unlucky fish. Great Ben a like shot, nice toning.', '2011-07-21 21:25:18.000000', NULL, 1),
(6478010, 961162, 119419, '<td valign="top">Good energy and immediacy</td>', 'Good energy and immediacy', '2011-07-21 21:26:07.000000', NULL, 1),
(6478011, 961958, 119419, '<td valign="top">Like the grain and the white border, gives that traveler feeling.</td>', 'Like the grain and the white border, gives that traveler feeling.', '2011-07-21 21:27:10.000000', NULL, 1),
(6478014, 962217, 117037, '<td valign="top">Feel the sense of Ben''s on this image.</td>', 'Feel the sense of Ben''s on this image.', '2011-07-21 21:43:24.000000', NULL, 1),
(6478016, 961404, 117037, '<td valign="top">So pure and beautiful.</td>', 'So pure and beautiful.', '2011-07-21 21:46:25.000000', NULL, 1),
(6478018, 961453, 117037, '<td valign="top">Lovely image...the wave brings back the sweetest reminiscence.</td>', 'Lovely image...the wave brings back the sweetest reminiscence.', '2011-07-21 21:54:38.000000', NULL, 1),
(6478024, 961587, 117037, '<td valign="top">I can''t figure this out but I sense the beauty, well done.</td>', 'I can''t figure this out but I sense the beauty, well done.', '2011-07-21 21:58:26.000000', NULL, 1),
(6478025, 961757, 117037, '<td valign="top">Beautiful sunset.</td>', 'Beautiful sunset.', '2011-07-21 21:59:46.000000', NULL, 1),
(6478027, 961811, 64086, '<td valign="top">Beautiful light draped across the mysterious figure and the land. I can feel the warmth.</td>', 'Beautiful light draped across the mysterious figure and the land. I can feel the warmth.', '2011-07-21 22:00:51.000000', NULL, 1),
(6478031, 961450, 64086, '<td valign="top">Such a rush of energy but still quite delicate. Beautiful photo.</td>', 'Such a rush of energy but still quite delicate. Beautiful photo.', '2011-07-21 22:04:43.000000', NULL, 1),
(6478032, 961191, 64086, '<td valign="top">Amazingly dreamy watery painting, perfectly composed.</td>', 'Amazingly dreamy watery painting, perfectly composed.', '2011-07-21 22:05:37.000000', NULL, 1),
(6478037, 962259, 100831, '<td valign="top">this one''s got my attention... nice tilt, excellent stance, and I like the other worldly feel to it.</td>', 'this one''s got my attention... nice tilt, excellent stance, and I like the other worldly feel to it.', '2011-07-21 22:22:56.000000', NULL, 1),
(6478040, 961582, 100831, '<td valign="top">very cool - she jumped right out of the frame - high contrasts for Ben!</td>', 'very cool - she jumped right out of the frame - high contrasts for Ben!', '2011-07-21 22:24:52.000000', NULL, 1),
(6478045, 962238, 94815, '<td valign="top">Good bw and very evocative of a plaintive childhood expression.</td>', 'Good bw and very evocative of a plaintive childhood expression.', '2011-07-21 22:35:44.000000', NULL, 1),
(6478047, 962256, 94815, '<td valign="top">Children play an important role in Ben''s work and you have captured his kind of candid shots that have a compelling inner-directed mood.</td>', 'Children play an important role in Ben''s work and you have captured his kind of candid shots that have a compelling inner-directed mood.', '2011-07-21 22:37:09.000000', NULL, 1),
(6478048, 961450, 94815, '<td valign="top">This reminds me of the painter Frances Bacon maybe more than Ben but I''m giving it a 7 for its special soul bearing sentiment even if not intended.</td>', 'This reminds me of the painter Frances Bacon maybe more than Ben but I''m giving it a 7 for its special soul bearing sentiment even if not intended.', '2011-07-21 22:37:36.000000', NULL, 1),
(6478049, 962259, 94815, '<td valign="top">Wow quite a find with that monolythic figure in its noirish atmosphere - stong, even threatening.</td>', 'Wow quite a find with that monolythic figure in its noirish atmosphere - stong, even threatening.', '2011-07-21 22:37:49.000000', NULL, 1),
(6478050, 962246, 94815, '<td valign="top">Wonderfully elemental and surprising candid of a landmark event in our respective lives.</td>', 'Wonderfully elemental and surprising candid of a landmark event in our respective lives.', '2011-07-21 22:40:48.000000', NULL, 1),
(6478051, 961159, 94815, '<td valign="top">Excellent bw rendering and just the right amount of blur (short of the silly silky stuff some prefer) makes this a treat for my eye as well as a thoughtful image of the genesis of life itself.</td>', 'Excellent bw rendering and just the right amount of blur (short of the silly silky stuff some prefer) makes this a treat for my eye as well as a thoughtful image of the genesis of life itself.', '2011-07-21 22:41:07.000000', NULL, 1),
(6478052, 961724, 76335, '<td valign="top">So many possibilities here. The poetry is darker than anything of Ben''s I''ve read. I know it''s something he''ll appreciate. Certainly, I do.</td>', 'So many possibilities here. The poetry is darker than anything of Ben''s I''ve read. I know it''s something he''ll appreciate. Certainly, I do.', '2011-07-21 22:41:20.000000', NULL, 1),
(6478053, 961126, 94815, '<td valign="top">Ben''s stuff frequently reaches back inside our elemental selves. This reaches way back to the primordial murk of those elements before they coalesced into what we have become - for better or worse.</td>', 'Ben''s stuff frequently reaches back inside our elemental selves. This reaches way back to the primordial murk of those elements before they coalesced into what we have become - for better or worse.', '2011-07-21 22:41:51.000000', NULL, 1),
(6478054, 961130, 94815, '<td valign="top">Like many of Ben''s images, this will be hard to forget. Good combination of blur and strong visual elements.</td>', 'Like many of Ben''s images, this will be hard to forget. Good combination of blur and strong visual elements.', '2011-07-21 22:42:03.000000', NULL, 1),
(6478055, 962298, 32011, '<td valign="top">This is a great image for this challenge.  The combination of sharpness and motion blur, the processing, the crop.  I love the old guy in the hat.  Composition is wonderful.  Well done.</td>', 'This is a great image for this challenge.  The combination of sharpness and motion blur, the processing, the crop.  I love the old guy in the hat.  Composition is wonderful.  Well done.', '2011-07-21 22:43:20.000000', NULL, 1),
(6478056, 962310, 76335, '<td valign="top">I think you made the right choice. Honestly, I didn''t see the children when you first showed this to me, and I wonder how many of our rapidfire voters <br/>missed them. The title invites us to look harder. Nice work.</td>', 'I think you made the right choice. Honestly, I didn''t see the children when you first showed this to me, and I wonder how many of our rapidfire voters missed them. The title invites us to look harder. Nice work.', '2011-07-21 22:43:34.000000', NULL, 1),
(6478058, 962155, 32011, '<td valign="top">Simply beautiful.  Processing is spot on.  The blurred seagulls.  Composition is great... there''s a beach and water... wonderful image for the challenge.</td>', 'Simply beautiful.  Processing is spot on.  The blurred seagulls.  Composition is great... there''s a beach and water... wonderful image for the challenge.', '2011-07-21 22:44:44.000000', NULL, 1),
(6478059, 962036, 94815, '<td valign="top">Something horrific about this shot as if she were just hung on the wall by the large brute. Well, anyway, that''s what comes to mind to someone who''s seen "The Texas Chainsaw Massacre" but I think it''s subject to many other interpretations. More surreal than Ben''s but maybe he just hasn''t gotton there yet.</td>', 'Something horrific about this shot as if she were just hung on the wall by the large brute. Well, anyway, that''s what comes to mind to someone who''s seen "The Texas Chainsaw Massacre" but I think it''s subject to many other interpretations. More surreal than Ben''s but maybe he just hasn''t gotton there yet.', '2011-07-21 22:47:06.000000', NULL, 1),
(6478060, 961191, 32011, '<td valign="top">This in a POWERFUL image.  Very powerful.  I only gave it a 6 in my voting phase, but as I go through commenting on some of the entries, I feel I was too harsh on this and feel an 8 is more appropriate for this.</td>', 'This in a POWERFUL image.  Very powerful.  I only gave it a 6 in my voting phase, but as I go through commenting on some of the entries, I feel I was too harsh on this and feel an 8 is more appropriate for this.', '2011-07-21 22:47:08.000000', NULL, 1),
(6478061, 961191, 94815, '<td valign="top">Moody.. the Spurgeon way.</td>', 'Moody.. the Spurgeon way.', '2011-07-21 22:47:19.000000', NULL, 1),
(6478062, 962218, 94815, '<td valign="top">I dunno if it''s Ben''s stuff and I never like borders but the rest works well with the bokeh echoing the round shape of the snail.</td>', 'I dunno if it''s Ben''s stuff and I never like borders but the rest works well with the bokeh echoing the round shape of the snail.', '2011-07-21 22:47:42.000000', NULL, 1),
(6478063, 962319, 94815, '<td valign="top">Filmy and impressionistic but not especially Benish. Still looks good. 6</td>', 'Filmy and impressionistic but not especially Benish. Still looks good. 6', '2011-07-21 22:47:52.000000', NULL, 1),
(6478064, 962292, 94815, '<td valign="top">Freedom indeed - the spirit well conveyed with lovely blur.</td>', 'Freedom indeed - the spirit well conveyed with lovely blur.', '2011-07-21 22:48:35.000000', NULL, 1),
(6478066, 962124, 32011, '<td valign="top">Great composition.  It has a certain quality, character, that holds ones attention... sit here looking at it wondering about the woman in silhouette.  Excellent use of back lighting.  Beautiful work.</td>', 'Great composition.  It has a certain quality, character, that holds ones attention... sit here looking at it wondering about the woman in silhouette.  Excellent use of back lighting.  Beautiful work.', '2011-07-21 22:50:44.000000', NULL, 1),
(6478068, 961933, 32011, '<td valign="top">Great image.  I''d never have thought to do croquet for this challenge, but you''ve do it here extremely well.  Bravo!  Processing, crop, blur + sharpness... all Ben to a tee.</td>', 'Great image.  I''d never have thought to do croquet for this challenge, but you''ve do it here extremely well.  Bravo!  Processing, crop, blur + sharpness... all Ben to a tee.', '2011-07-21 22:53:06.000000', NULL, 1),
